<?php
session_start(); require __DIR__.'/config.php'; require_once __DIR__.'/github-data.php';
$dir=__DIR__.'/data'; $settingsFile=$dir.'/settings.json'; $devicesFile=$dir.'/devices.json';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function redir(){header('Location: index.php');exit;}
function jsonread($f,$d){if(!is_file($f))return $d;$v=json_decode(file_get_contents($f),true);return is_array($v)?$v:$d;} function jsonsave($f,$v){if(!is_dir(dirname($f)))mkdir(dirname($f),0755,true);file_put_contents($f,json_encode($v,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE),LOCK_EX);}
function token(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}
function encpath($p){return implode('/',array_map('rawurlencode',explode('/',trim($p,'/'))));}
function github($method,$path,$body=null){$url='https://api.github.com/repos/'.rawurlencode(GITHUB_OWNER).'/'.rawurlencode(GITHUB_REPOSITORY).'/contents/'.encpath($path);if($method==='GET')$url.='?ref='.rawurlencode(GITHUB_BRANCH);$headers=['Accept: application/vnd.github+json','Authorization: Bearer '.GITHUB_TOKEN,'X-GitHub-Api-Version: 2022-11-28','User-Agent: ConfigBox-Admin'];$c=curl_init($url);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$headers,CURLOPT_CONNECTTIMEOUT=>20,CURLOPT_TIMEOUT=>120]);if($body!==null){$headers[]='Content-Type: application/json';curl_setopt($c,CURLOPT_HTTPHEADER,$headers);curl_setopt($c,CURLOPT_POSTFIELDS,json_encode($body,JSON_UNESCAPED_UNICODE));}$r=curl_exec($c);$err=curl_error($c);$code=(int)curl_getinfo($c,CURLINFO_HTTP_CODE);curl_close($c);if($r===false||$err)throw new Exception('Falha de conexão com o GitHub: '.$err);$j=json_decode($r,true);if($code<200||$code>=300)throw new Exception(is_array($j)&&isset($j['message'])?$j['message']:'GitHub HTTP '.$code);return $j;}
function files($folder){$items=github('GET',$folder);$out=[];if(!is_array($items))return $out;foreach($items as $i)if(($i['type']??'')==='file'&&!in_array(($i['name']??''),['.gitkeep','.keep','README.md'],true))$out[]=['name'=>$i['name']??'','path'=>$i['path']??'','sha'=>$i['sha']??'','size'=>(int)($i['size']??0),'url'=>$i['download_url']??''];usort($out,function($a,$b){return strcasecmp($a['name'],$b['name']);});return $out;}
function safename($n){$n=trim(basename($n));if($n===''||$n==='.'||$n==='..'||strpos($n,"\0")!==false)throw new Exception('Nome de arquivo inválido.');return $n;} function sizefmt($n){return $n<1024?$n.' B':($n<1048576?round($n/1024,1).' KB':round($n/1048576,1).' MB');}
function authpost(){if(empty($_SESSION['admin']))redir();if(!isset($_POST['csrf'])||!hash_equals($_SESSION['csrf']??'',$_POST['csrf']))throw new Exception('Sessão expirada. Atualize a página.');}
$settings=jsonread($settingsFile,['plan_active'=>true,'lock_message'=>'','dialog_message'=>'']);$devices=github_devices_read()['items'];$msg=null;$error=false;
try{
 if(isset($_GET['logout'])){session_destroy();redir();}
 if(isset($_POST['login'])){if(!hash_equals(ADMIN_PASSWORD,(string)($_POST['password']??'')))throw new Exception('Senha inválida.');$_SESSION['admin']=true;token();redir();}
 if($_SERVER['REQUEST_METHOD']==='POST'&&!isset($_POST['login'])){authpost();
  if(isset($_POST['save_control'])){$settings['plan_active']=isset($_POST['plan_active']);$settings['lock_message']=trim($_POST['lock_message']??'');$settings['dialog_message']=trim($_POST['dialog_message']??'');jsonsave($settingsFile,$settings);$msg='Controle salvo.';}
  if(isset($_POST['delete_config'])){$name=safename($_POST['name']??'');if(in_array($name,['.gitkeep','.keep','README.md'],true))throw new Exception('Arquivo de manutenção não pode ser excluído.');github('DELETE',GITHUB_CONFIG_FOLDER.'/'.$name,['message'=>'Excluir configuração '.$name,'sha'=>$_POST['sha']??'','branch'=>GITHUB_BRANCH]);$msg='Configuração excluída: '.$name;}
  if(isset($_POST['delete_apk'])){$name=safename($_POST['name']??'');if(in_array($name,['.gitkeep','.keep','README.md'],true))throw new Exception('Arquivo de manutenção não pode ser excluído.');github('DELETE',GITHUB_APK_FOLDER.'/'.$name,['message'=>'Excluir APK '.$name,'sha'=>$_POST['sha']??'','branch'=>GITHUB_BRANCH]);$msg='APK excluído.';}
  if(isset($_POST['device_action'])){$id=$_POST['device_id']??'';foreach($devices as &$d)if(($d['device_id']??'')===$id){$d['blocked']=$_POST['device_action']==='block';$d['message']=trim($_POST['device_message']??'');}unset($d);$gd=github_devices_read(); github_devices_write(array_values($devices),$gd['sha']);$msg='Aparelho atualizado.';}
  if(isset($_POST['upload_configs'])){$old=files(GITHUB_CONFIG_FOLDER);$map=[];foreach($old as $f)$map[$f['name']]=$f;$up=$_FILES['configs']??null;if(!$up||!is_array($up['name']))throw new Exception('Escolha as configurações.');$n=0;foreach($up['name'] as $i=>$orig){if(($up['error'][$i]??4)!==0)continue;$name=safename($orig);$b=['message'=>(isset($map[$name])?'Atualizar ':'Adicionar ').$name,'content'=>base64_encode(file_get_contents($up['tmp_name'][$i])),'branch'=>GITHUB_BRANCH];if(isset($map[$name]))$b['sha']=$map[$name]['sha'];github('PUT',GITHUB_CONFIG_FOLDER.'/'.$name,$b);$n++;}$msg=$n.' configuração(ões) enviada(s).';}
  if(isset($_POST['save_unitv_url'])){$url=trim((string)($_POST['unitv_url']??''));if($url!==''&&!filter_var($url,FILTER_VALIDATE_URL))throw new Exception('Informe uma URL válida do APK.');$link=github_link_read();github_link_write($url,$link['sha']);$msg=$url===''?'Link do UniTV removido.':'Link do UniTV salvo.';}
 }
}catch(Throwable $x){$msg=$x->getMessage();$error=true;}
$logged=!empty($_SESSION['admin']);$configs=[];$apks=[];$unitvLink=['url'=>''];if($logged)try{$configs=files(GITHUB_CONFIG_FOLDER);$unitvLink=github_link_read();$devices=github_devices_read()['items'];}catch(Throwable $x){$msg=$x->getMessage();$error=true;}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ConfigBox Admin</title><style>
:root{font-family:system-ui,-apple-system,Segoe UI,sans-serif;color:#17243b;background:#f5f7fb}*{box-sizing:border-box}body{margin:0}.shell{max-width:1060px;margin:auto;padding:24px 16px 55px}.card{background:#fff;border:1px solid #e3e9f2;border-radius:18px;padding:20px;margin:16px 0;box-shadow:0 7px 25px #1e3a5f0b}.login{max-width:420px;margin:12vh auto}.head{display:flex;align-items:center;justify-content:space-between;gap:16px}.brand{display:flex;gap:12px;align-items:center}.logo{width:43px;height:43px;border-radius:13px;background:#2563eb;color:#fff;display:grid;place-items:center;font-weight:900;font-size:20px}.eyebrow{color:#2563eb;font-size:11px;font-weight:900;letter-spacing:1.2px;margin:0 0 4px}.title{font-size:26px;margin:0;letter-spacing:-.5px}.sub,.muted{color:#6d7b91;font-size:13px}.repo{margin-top:18px;padding:13px;border-radius:12px;background:#eaf2ff;color:#2458a8;font:13px monospace;overflow:auto}.notice{padding:12px 14px;border-radius:11px;margin:16px 0;font-size:14px}.success{background:#e8f8ee;color:#176b3c}.error{background:#fff0f0;color:#a51d1d}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:14px}.section-head h2{font-size:19px;margin:0}.count{background:#e8eefb;color:#31599d;border-radius:99px;padding:5px 10px;font-size:12px;font-weight:800}.input,.textarea{width:100%;border:1px solid #d3ddea;border-radius:10px;padding:11px;font:inherit;margin:5px 0 12px;background:#fcfdff}.textarea{min-height:80px;resize:vertical}.button{display:inline-flex;border:0;border-radius:10px;padding:11px 14px;font:inherit;font-weight:800;cursor:pointer;text-decoration:none;justify-content:center}.primary{background:#2563eb;color:white}.secondary{background:#edf2f8;color:#29415f}.danger{background:#fff0f0;color:#aa211b}.file-list{display:flex;flex-direction:column;gap:9px;margin-top:14px}.file-row{display:flex;align-items:center;gap:10px;border:1px solid #e3eaf3;border-radius:12px;padding:11px}.icon{width:37px;height:37px;border-radius:10px;background:#eff6ff;color:#2563eb;display:grid;place-items:center;font-size:11px;font-weight:900;flex:none}.file-info{min-width:0;flex:1}.file-name{font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.file-meta{font-size:12px;color:#7a8799;margin-top:3px}.file-actions{display:flex;gap:6px;flex:none}.empty{border:1px dashed #cbd6e5;border-radius:12px;padding:20px;text-align:center;color:#7b889a;font-size:13px}.device{border:1px solid #e3eaf3;border-radius:12px;padding:14px;margin-top:9px}.device-top{display:flex;justify-content:space-between;gap:10px}.device-info{min-width:0}.device-info strong{display:block}.device-info small{display:block;color:#718096;margin-top:4px;word-break:break-word}.badge{font-size:11px;border-radius:99px;padding:5px 9px;background:#e8f8ee;color:#176b3c;height:max-content;white-space:nowrap}.badge.blocked{background:#fff0f0;color:#a51d1d}.device form{margin-top:10px}.footer{text-align:center;color:#8794a7;font-size:12px}@media(max-width:720px){.grid{grid-template-columns:1fr}.title{font-size:23px}.file-row{align-items:flex-start;flex-wrap:wrap}.file-info{min-width:calc(100% - 50px)}.file-actions{width:100%;padding-left:47px}.file-actions .button{flex:1}.head{align-items:flex-start}}
</style></head><body><main class="shell"><?php if(!$logged):?><section class="card login"><div class="brand"><div class="logo">C</div><div><p class="eyebrow">CONFIGBOX ADMIN</p><h1 class="title">Entrar no painel</h1></div></div><p class="sub">Gerencie configurações, APK e aparelhos.</p><?php if($msg):?><div class="notice error"><?=h($msg)?></div><?php endif;?><form method="post"><input class="input" type="password" name="password" placeholder="Senha administrativa" required><button class="button primary" style="width:100%" name="login" value="1">Entrar</button></form></section><?php else:?><header class="head"><div class="brand"><div class="logo">C</div><div><p class="eyebrow">PAINEL ADMINISTRATIVO</p><h1 class="title">ConfigBox</h1><p class="sub">Arquivos e controle do ativador</p></div></div><a class="button secondary" href="?logout=1">Sair</a></header><div class="repo"><?=h(GITHUB_OWNER.'/'.GITHUB_REPOSITORY)?> · <?=h(GITHUB_BRANCH)?></div><?php if($msg):?><div class="notice <?=$error?'error':'success'?>"><?=h($msg)?></div><?php endif;?><section class="card"><div class="section-head"><h2>Controle do aplicativo</h2><span class="count">Acesso remoto</span></div><form method="post"><input type="hidden" name="csrf" value="<?=h(token())?>"><label><input type="checkbox" name="plan_active" <?=$settings['plan_active']?'checked':''?>> Ativador liberado</label><label class="muted">Mensagem quando bloqueado<textarea class="textarea" name="lock_message"><?=h($settings['lock_message']??'')?></textarea></label><label class="muted">Diálogo ao abrir o app<textarea class="textarea" name="dialog_message"><?=h($settings['dialog_message']??'')?></textarea></label><button class="button primary" name="save_control" value="1">Salvar controle</button></form></section><div class="grid"><section class="card"><div class="section-head"><h2>Configurações</h2><span class="count"><?=count($configs)?></span></div><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(token())?>"><input class="input" type="file" name="configs[]" multiple><button class="button primary" name="upload_configs" value="1">Enviar configurações</button></form><div class="file-list"><?php if(!$configs):?><div class="empty">Nenhuma configuração em <b><?=h(GITHUB_CONFIG_FOLDER)?></b>.</div><?php else:foreach($configs as $f):?><div class="file-row"><div class="icon">CFG</div><div class="file-info"><div class="file-name" title="<?=h($f['name'])?>"><?=h($f['name'])?></div><div class="file-meta"><?=h(sizefmt($f['size']))?></div></div><div class="file-actions"><a class="button secondary" target="_blank" href="<?=h($f['url'])?>">Abrir</a><form method="post" onsubmit="return confirm('Excluir <?=h($f['name'])?>?')"><input type="hidden" name="csrf" value="<?=h(token())?>"><input type="hidden" name="name" value="<?=h($f['name'])?>"><input type="hidden" name="sha" value="<?=h($f['sha'])?>"><button class="button danger" name="delete_config" value="1">Excluir</button></form></div></div><?php endforeach;endif;?></div></section><section class="card"><div class="section-head"><h2>Link do APK UniTV</h2><span class="count">URL direta</span></div><p class="muted">Cole o link direto para o arquivo .apk. O botão do aplicativo consultará este endereço e abrirá a instalação depois do download.</p><form method="post"><input type="hidden" name="csrf" value="<?=h(token())?>"><input class="input" type="url" name="unitv_url" value="<?=h(($unitvLink['url']??''))?>" placeholder="https://servidor.com/unitv.apk"><button class="button primary" name="save_unitv_url" value="1">Salvar link do APK</button></form><p class="muted">O link fica salvo em <b>admin-data/unitv-link.json</b> no GitHub.</p></section></div><section class="card"><div class="section-head"><h2>Aparelhos cadastrados</h2><span class="count"><?=count($devices)?></span></div><?php if(!$devices):?><div class="empty">Nenhum aparelho consultou o Admin ainda.</div><?php else:foreach($devices as $d):?><div class="device"><div class="device-top"><div class="device-info"><strong><?=h($d['model']??'Modelo desconhecido')?></strong><small>Android ID: <?=h($d['device_id']??'')?></small><small>IMEI: <?=h($d['imei']??'não disponível')?> · <?=h($d['last_seen']??'')?></small></div><span class="badge <?=$d['blocked']?'blocked':''?>"><?=$d['blocked']?'Bloqueado':'Liberado'?></span></div><form method="post"><input type="hidden" name="csrf" value="<?=h(token())?>"><input type="hidden" name="device_id" value="<?=h($d['device_id']??'')?>"><input class="input" name="device_message" placeholder="Mensagem para este aparelho" value="<?=h($d['message']??'')?>"><button class="button <?=$d['blocked']?'primary':'danger'?>" name="device_action" value="<?=$d['blocked']?'unblock':'block'?>"><?=$d['blocked']?'Desbloquear aparelho':'Bloquear aparelho'?></button></form></div><?php endforeach;endif;?></section><p class="footer">Android ID é o identificador principal. O IMEI pode não estar disponível em versões recentes.</p><?php endif;?></main></body></html>
